        evidence["gpu_index"]=gpu;evidence["lighting_path"]=mode;evidence["samples"]=samples;evidence["scope"]="Binary alpha masking; controlled rigid/weighted cards, original products, shadow coverage and independent4x foreground. No A2C, blending, mip-coverage, foliage-performance or alpha-aware physics claim.";
