        auto background=object("background",quad(4),{0,0,-4},{0,.7f,0});background.cast_shadows=false;auto card=object("card",rigid,{0,0,-2},{.7f,0,0});card.textures=alpha128;
        std::vector<std::array<unsigned,2>> points;for(auto uv:{std::array<double,2>{.125,.125},{.375,.125},{.625,.625},{.875,.625}})points.push_back(pixel_at((uv[0]-.5)*1.6,(uv[1]-.5)*1.6,2));
        RenderOptions options;options.gpu=gpu;options.width=width;options.height=height;options.samples=samples;options.viewmodel_samples=4;options.deferred=mode=="deferred";options.frames_in_flight=2;options.capture_exclusive=true;if(samples==1)for(auto p:points)options.scene_product_probes.push_back({p[0],p[1]});state.objects={background};Window window;HostedViewport view(options,state,window.child);unsigned sequence=0;std::string gpu_name;
