        state.objects={background};auto foreground=object("foreground",quad(.4f),{0,0,-1},{.7f,0,0});foreground.cast_shadows=false;foreground.textures=alpha128;state.viewmodel=SceneViewmodel{{60,.01,4},{foreground}};++state.material_revision;const auto foreopaque=capture("foreground-opaque");state.viewmodel->objects[0].material->alpha_mode=MaterialAlphaMode::mask;state.viewmodel->objects[0].material->alpha_cutoff=.4f;++state.material_revision;const auto foremask=capture("foreground-mask");evidence["checks"]["foreground_coverage"]=checker_oracle(foremask.first,foreopaque.first,bg.first);state.viewmodel->objects[0].material->alpha_cutoff=1e6f;++state.material_revision;const auto foregone=capture("foreground-fully-discarded");evidence["checks"]["foreground_discard_whole_image_error"]=compare(foregone.first,bg.first);
        if(samples==1)for(const auto* rendered:{&foreopaque.second,&foremask.second,&foregone.second})for(const auto& p:rendered->diagnostics.scene_products.probes){require_near(p.depth,40./39.9-4./39.9/4,3e-6,"Foreground mask contaminated world depth.");require_near(p.motion[0],0,4e-6,"Foreground mask contaminated world motion.");}
        check(foremask.second.diagnostics.viewmodel&&foremask.second.diagnostics.viewmodel->samples==4&&foremask.second.diagnostics.viewmodel->rendered,"Independent4x foreground path absent.");
        state.viewmodel.reset();auto receiver=background;receiver.material->base_color={.7f,.7f,.7f};receiver.material->emissive={0,0,0};state.objects={receiver};state.lighting.environment.ambient={.02f,.02f,.02f};state.lighting.environment.shadow_resolution=1024;SceneLight light;light.entity_id="sun";light.light.kind=LightKind::directional;light.light.intensity=4;light.light.shadow.enabled=true;light.light.shadow.distance=8;light.light.shadow.bias=.00005f;light.light.shadow.normal_bias=.001f;light.direction={-.6,0,-.8};state.lighting.lights={light};++state.material_revision;const auto lit=capture("shadow-receiver-control");
